//! Registry lookups beyond the per-version data: the small registries 1.13
//! had before the server reported them, the vanilla entries of data-driven
//! registries, and the vanilla tag sets of every protocol, all generated by
//! `scripts/translation_tags.py` into `data/tags/`.
use crate::{
    Direction,
    codec::Shared,
    data::{self, Registry, strip},
    mapping::Mapping,
};
use serde_json::Value;
use std::{
    collections::{BTreeMap, HashMap},
    sync::{Mutex, OnceLock},
};

/// A tag's name and its entries' names.
pub type Tag = (&'static str, Vec<&'static str>);

/// One protocol's vanilla tags: per registry, tag names with their entry
/// names, both without the `minecraft:` namespace, sorted by name.
pub struct VanillaTags {
    pub registries: Vec<(&'static str, Vec<Tag>)>,
}

impl VanillaTags {
    pub fn registry(&self, name: &str) -> Option<&[Tag]> {
        let name = strip(name);
        self.registries
            .iter()
            .find(|(registry, _)| *registry == name)
            .map(|(_, tags)| &tags[..])
    }
}

struct Vanilla {
    tags: VanillaTags,
    /// Vanilla entries of the data-driven registries the tags refer to.
    entries: Vec<(&'static str, Registry)>,
}

fn file(stem: &str) -> &'static Value {
    data::file(stem).unwrap_or_else(|| panic!("missing data/{stem}.json"))
}

fn strings(value: &'static Value) -> Vec<&'static str> {
    value
        .as_array()
        .expect("a list of names")
        .iter()
        .map(|name| name.as_str().expect("a name"))
        .collect()
}

/// Replay the per-protocol changes of `vanilla.json` up to `protocol`.
fn vanilla(protocol: i32) -> Option<&'static Vanilla> {
    static CACHE: OnceLock<Mutex<HashMap<i32, Option<&'static Vanilla>>>> = OnceLock::new();
    let mut cache = CACHE.get_or_init(Default::default).lock().unwrap();
    *cache.entry(protocol).or_insert_with(|| {
        let protocols = file("tags/vanilla")["protocols"].as_object()?;
        protocols.get(&protocol.to_string())?;
        let mut tags: BTreeMap<&str, BTreeMap<&str, Vec<&str>>> = BTreeMap::new();
        let mut entries: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
        let mut ordered: Vec<(i32, &Value)> = protocols
            .iter()
            .map(|(key, change)| (key.parse().expect("protocol key"), change))
            .collect();
        ordered.sort_by_key(|(key, _)| *key);
        for (key, change) in ordered.into_iter().take_while(|(key, _)| *key <= protocol) {
            let _ = key;
            for (registry, value) in change["tags"].as_object().expect("tags") {
                match value.as_object() {
                    None => drop(tags.remove(registry.as_str())),
                    Some(changed) => {
                        let registry = tags.entry(registry.as_str()).or_default();
                        for (tag, list) in changed {
                            if list.is_null() {
                                registry.remove(tag.as_str());
                            } else {
                                registry.insert(tag.as_str(), strings(list));
                            }
                        }
                    }
                }
            }
            for (registry, list) in change["entries"].as_object().expect("entries") {
                if list.is_null() {
                    entries.remove(registry.as_str());
                } else {
                    entries.insert(registry.as_str(), strings(list));
                }
            }
        }
        let vanilla = Vanilla {
            tags: VanillaTags {
                registries: tags
                    .into_iter()
                    .map(|(registry, tags)| (registry, tags.into_iter().collect()))
                    .collect(),
            },
            entries: entries
                .into_iter()
                .map(|(registry, names)| {
                    let names = names
                        .into_iter()
                        .map(|name| Some(name.to_owned()))
                        .collect();
                    (registry, Registry::new(names))
                })
                .collect(),
        };
        Some(&*Box::leak(Box::new(vanilla)))
    })
}

/// The tags the official server of `protocol` sends, or `None` before 1.13.
pub fn vanilla_tags(protocol: i32) -> Option<&'static VanillaTags> {
    vanilla(protocol).map(|vanilla| &vanilla.tags)
}

/// A small registry `misc.json` holds for 1.13, keyed by protocol.
fn legacy(protocol: i32, name: &str) -> Option<&'static Registry> {
    type Cache = HashMap<(i32, String), Option<&'static Registry>>;
    static CACHE: OnceLock<Mutex<Cache>> = OnceLock::new();
    let mut cache = CACHE.get_or_init(Default::default).lock().unwrap();
    *cache.entry((protocol, name.to_owned())).or_insert_with(|| {
        let names = file("tags/misc").get(name)?.get(protocol.to_string())?;
        let names = strings(names)
            .into_iter()
            .map(|name| Some(name.to_owned()))
            .collect();
        Some(&*Box::leak(Box::new(Registry::new(names))))
    })
}

/// Where a registry's IDs come from in one protocol.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    /// The per-version data: a built-in registry.
    BuiltIn,
    /// `misc.json`: a built-in registry 1.13 did not report.
    Legacy,
    /// A data-driven registry, numbered as the vanilla server numbers it.
    Vanilla,
}

/// The registry `name` of `protocol` and where it comes from. Data-driven
/// registries are known only when vanilla tags refer to them.
pub fn registry(protocol: i32, name: &str) -> Option<(Kind, &'static Registry)> {
    let name = strip(name);
    if let Some(registry) = data::version(protocol).registry(name) {
        return Some((Kind::BuiltIn, registry));
    }
    if let Some(registry) = legacy(protocol, name) {
        return Some((Kind::Legacy, registry));
    }
    // INTEGRATION: data-driven registries are numbered by what the backend
    // really synchronised; the registries codec should expose that per
    // connection. Until it does, assume the vanilla server's numbering.
    vanilla(protocol)?
        .entries
        .iter()
        .find(|(registry, _)| *registry == name)
        .map(|(_, registry)| (Kind::Vanilla, registry))
}

/// The registry's name as the per-version data spells it, borrowed for as
/// long as the data lives (which [`Shared::mapping`] needs).
fn static_name(protocol: i32, name: &str) -> Option<&'static str> {
    data::version(protocol)
        .registry_names()
        .find(|known| *known == name)
}

/// Sender's ID to receiver's ID of the registry `name` for packets in
/// `direction`, or `None` when either side lacks the registry. Built-in
/// registries go through [`Shared::mapping`] (with each step's rename and
/// stand-in rules); others map by name.
pub fn mapping(shared: &mut Shared, direction: Direction, name: &str) -> Option<&'static Mapping> {
    let name = strip(name);
    let (source, target) = (shared.source(direction), shared.target(direction));
    let (source_kind, _) = registry(source, name)?;
    let (target_kind, _) = registry(target, name)?;
    if source_kind == Kind::BuiltIn && target_kind == Kind::BuiltIn {
        let name = static_name(source, name)?;
        return Some(shared.mapping(direction, name));
    }
    Some(by_name(source, target, name))
}

/// A mapping by entry name between two protocols' registries that are not
/// both built in.
fn by_name(source: i32, target: i32, name: &str) -> &'static Mapping {
    type Key = (i32, i32, String);
    static CACHE: OnceLock<Mutex<HashMap<Key, &'static Mapping>>> = OnceLock::new();
    let key = (source, target, name.to_owned());
    if let Some(mapping) = CACHE
        .get_or_init(Default::default)
        .lock()
        .unwrap()
        .get(&key)
    {
        return mapping;
    }
    let (_, from) = registry(source, name).expect("source registry");
    let (_, to) = registry(target, name).expect("target registry");
    let table = (0..from.len() as i32)
        .map(|id| from.name(id).and_then(|name| to.id(name)).unwrap_or(-1))
        .collect();
    let mapping: &'static Mapping = Box::leak(Box::new(Mapping::new(table)));
    CACHE
        .get_or_init(Default::default)
        .lock()
        .unwrap()
        .insert(key, mapping);
    mapping
}

/// Whether IDs of `name` need no rewriting from `source` to `target`:
/// both sides have it and number every shared entry the same.
pub fn unchanged(source: i32, target: i32, name: &str) -> bool {
    let (Some((source_kind, from)), Some((target_kind, _))) =
        (registry(source, name), registry(target, name))
    else {
        return false;
    };
    let mapping = if source_kind == Kind::BuiltIn && target_kind == Kind::BuiltIn {
        match static_name(source, strip(name)) {
            Some(name) => crate::mapping::mapping(source, target, name),
            None => return false,
        }
    } else {
        by_name(source, target, strip(name))
    };
    mapping.len() == from.len() && mapping.is_identity()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn small_and_data_driven_registries_resolve() {
        let (kind, stats) = registry(393, "custom_stat").unwrap();
        assert_eq!(kind, Kind::Legacy);
        assert_eq!(stats.name(0), Some("leave_game"));
        assert_eq!(registry(477, "custom_stat").unwrap().0, Kind::BuiltIn);
        assert_eq!(registry(393, "fluid").unwrap().1.id("water"), Some(2));
        let (kind, biomes) = registry(758, "worldgen/biome").unwrap();
        assert_eq!(kind, Kind::Vanilla);
        assert_eq!(biomes.name(0), Some("the_void"));
        let (_, biomes) = registry(761, "minecraft:worldgen/biome").unwrap();
        assert_eq!(biomes.name(0), Some("badlands"));
        assert!(registry(757, "worldgen/biome").is_none());
        assert!(registry(393, "menu").is_none());
    }

    #[test]
    fn vanilla_tags_replay_to_each_protocol() {
        assert!(vanilla_tags(340).is_none());
        let tags = vanilla_tags(393).unwrap();
        let names: Vec<&str> = tags.registries.iter().map(|(name, _)| *name).collect();
        assert_eq!(names, ["block", "fluid", "item"]);
        let water = tags.registry("minecraft:fluid").unwrap();
        assert_eq!(
            water.iter().find(|(tag, _)| *tag == "water").unwrap().1,
            ["water", "flowing_water"]
        );
        let newest = vanilla_tags(777).unwrap();
        assert!(newest.registry("timeline").is_some());
        assert!(vanilla_tags(769).unwrap().registry("cat_variant").is_some());
        assert!(vanilla_tags(770).unwrap().registry("cat_variant").is_none());
    }

    #[test]
    fn mappings_cover_every_kind_of_registry() {
        let mut shared = Shared::new(477, 404);
        let stats = mapping(&mut shared, Direction::Clientbound, "custom_stat").unwrap();
        assert_eq!(stats.get(0), Some(0));
        let mut shared = Shared::new(761, 760);
        let biomes = mapping(&mut shared, Direction::Clientbound, "worldgen/biome").unwrap();
        // 1.19.2 numbers biomes in code order (the void first), 1.19.3 by name.
        let plains = registry(760, "worldgen/biome")
            .unwrap()
            .1
            .id("plains")
            .unwrap();
        let expected = registry(761, "worldgen/biome").unwrap().1.id("plains");
        assert_eq!(biomes.get(plains), expected);
        assert!(mapping(&mut shared, Direction::Clientbound, "no_such_registry").is_none());
        assert!(unchanged(498, 490, "block"));
        assert!(!unchanged(760, 761, "worldgen/biome"));
    }
}
